        setup: GS('gb1-1') + '\ngit init -q --bare remote.git\ngit clone -q remote.git web && cd web && echo "# todo-app" > README.md && echo "MIT License" > LICENSE && git add . && git commit -qm "Initial commit" && git push -q origin main && cd ..\nmkdir mine && cd mine && git init -q -b main\necho "print(\'할 일\')" > todo.py && printf \'%s\\n\' "__pycache__/" ".env" > .gitignore && git add . && git commit -qm "할 일 앱 시작"\ngit remote add origin ../remote.git',
